<template>
 <div class="text-center">
                <h4>TYRES ASSEMBLY</h4>
                </div>
        <div class="d-flex  ">
                        <div class="ms-auto">
                            <button class="btn btn-outline-primary " @click="tyre_assembly =! tyre_assembly;   getTyreList()">                           
 <i class="bi bi-plus-square fs-4"></i>
</button>
 
                        </div>
                    </div>

                             <!--  registration form starts -->
 <form v-if="tyre_assembly" class="mt-3 p-3 border rounded bg-white shadow" @submit.prevent="registerTyreAssembly">
        <h6 class="text-center">REGISTER TYRE ASSEMBLY</h6>
        <div class="row mb-2">
    
            <div class="col-md-3">
            <label class="form-label small">Removed tyre</label>
            <multiselect 
    v-model="tyre_removed"
    :options="installedTyres"
    placeholder="select tyre"
    label="tyre_no"
    :searchable="true"
    :multiple="false"
    :required="true"
    :allow-empty="false"
></multiselect>
        </div>

            <div class="col-md-3">
            <label class="form-label small mb-1">
            <span v-if="loadingTyres" v-html="waitIndicator()"></span>
          <span v-else>Installed tyre</span>
            </label>
            
            <multiselect 
                v-model="tyre_installed"
                :options= "tyreList"
                placeholder="select tyre"
                label="tyre"
                :searchable = "true"        
                multple="false"
                :required="true"
                :allow-empty="false"
                :disabled="loadingTyres"
            ></multiselect>
        </div>
        <div class="col-md-3" >
                  <label class="form-label">Tyre Position</label>
                 <input type="text" v-model="position" class="form-control" placeholder="enter position" />

        </div>

            <div class="col-md-3" >
                    <label class="form-label">date</label>
                <input type="date" v-model="date" class="form-control" />
                </div>

        </div>
        <div class="text-center gap-2 justify-content-end">
            <button type="button" class="btn btn-danger me-3" @click="tyre_assembly = false; resetForm();">Cancel</button>
            <button type="submit" class="btn btn-primary" :disabled="loading_spinner" >
            <span v-if="loading_spinner" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
            Register
            </button>
        </div>
    </form>
             <!-- registration form ends-->

<div class="row layout-top-spacing ">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel br-6 p-0">
        <div v-if="loading" v-html="tableShimmer()"></div>
        <div v-else class="custom-table">
          <v-client-table :data="tyres" :columns="tyreColumns" :options="table_option">
            <template #status="props">
              <span 
                class="badge inv-status"
                :class="`badge-`+props.row.status.color" 
                style="cursor: pointer;"
              >
                {{ props.row.status.name }}
              </span>
            </template>

          </v-client-table>
        </div>
      </div>
      </div>
      </div>

</template>

<script setup>
import { ref, onMounted, inject, watch, computed } from 'vue';
import { useRoute } from 'vue-router';
const route = useRoute();
import axios from 'axios';
import Multiselect from '@suadelabs/vue3-multiselect';
import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
const tableShimmer = inject('tableShimmer')
const showError = inject('showError')
const waitIndicator = inject('waitIndicator')
const showMessage = inject('showMessage'); 

const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

 const tyre_assembly = ref(false);
 const loading = ref(false);
const tyres = ref([])
const tyreColumns = ref(['Sno','tyre_no', 'date_installed','date_removed','position','status']);

const installedTyres = computed(() => {
    return tyres.value.filter(tyre => tyre.tyre_status === 'INSTALLED');
});

   const getTyres = async() =>{
    loading.value = true
try{
    const response = await axiosInstance.get(`asset-assemblies?source=JOBCARD&source_id=${route.params.jobcard_id}`)
    tyres.value = response.data.map((item,index)=>({
      ...item,
      Sno : index + 1,
       tyre_status: item.status,
       status : {
        name : item.status ==='INSTALLED' ? 'IN USE' : 'REMOVED',
        color : item.status ==='INSTALLED' ? 'success' : 'dark'
      },
      tyre_no : item.child_asset,
          date_installed : item.installed_at ?? '---',
      date_removed : item.removed_at ?? '---' ,
      jobcard : item.source_id
}));
    }catch(error){
        console.log(error)
        showError(error.message)
    }finally{
        loading.value = false
    }
}


const loading_spinner = ref(false);
const tyre_removed = ref(null);
const tyre_installed = ref(null);
const position = ref('');
const date = ref('');

const registerTyreAssembly = async () => {
    loading_spinner.value = true;

    const payload = {
        parent_asset_id: route.params.machine_id, 
        removed_tyre_assembly_id: tyre_removed.value?.id ?? null, 
        installed_tyre_id: tyre_installed.value?.id ?? null, 
        position: position.value,
        date: date.value,
        source: 'JOBCARD',
        source_id:route.params.jobcard_id,
    };

    try {
        await axiosInstance.post('/tyre-assemblies', payload);
        getTyres();
        showMessage('Tyre assembly registered successfully!');
        tyre_assembly.value = false;
        resetForm();
    } catch (error) {
        showError(error.message);
        console.log(error)
    } finally {
        loading_spinner.value = false;
    }
};

const resetForm = () => {
    tyre_removed.value = null;
    tyre_installed.value = null;
    position.value = '';
    date.value = '';
};

 const tyreList = ref([]);
 const loadingTyres = ref(false);
    const getTyreList = async () => {
        loadingTyres.value = true
        try {
            const response = await axiosInstance.get('/tyres?assembly_status=REMOVED');
            tyreList.value = response.data.map((item,index)=>({
      ...item,
      Sno : index + 1,
       tyre:item.code +'-'+ item.condition,
        }));
        } catch (error) {
            showError(error.message);
            console.log(error)
        }finally{
            loadingTyres.value = false
        }
    };


onMounted(()=>{
    getTyres()
})

</script>